<?php
namespace App\Features\Identity\Controllers;
use App\Features\Identity\Repositories\UserRepository; use App\Features\Identity\Requests\UserRequest; use App\Features\Identity\Resources\UserResource; use App\Features\Identity\Services\UserService; use App\Http\Controllers\Controller; use Illuminate\Http\Request;
class UserController extends Controller { public function __construct(private UserRepository $users,private UserService $service){} public function index(Request $r){$this->authorize('viewAny',\App\Models\User::class);return UserResource::collection($this->users->paginate($r->user()->tenant_id,$r->query()));} public function store(UserRequest $r){return (new UserResource($this->service->create($r->validated(),$r->user(),$r)))->response()->setStatusCode(201);} public function show(Request $r,string $user){$model=$this->users->find($user,$r->user()->tenant_id);$this->authorize('view',$model);return new UserResource($model);} public function update(UserRequest $r,string $user){$model=$this->users->find($user,$r->user()->tenant_id);return new UserResource($this->service->update($model,$r->validated(),$r->user(),$r));} public function destroy(Request $r,string $user){$model=$this->users->find($user,$r->user()->tenant_id);$this->authorize('delete',$model);$this->service->delete($model,$r->user(),$r);return response()->json(['success'=>true,'message'=>'User deleted.','data'=>null]);} }
